    @Nullable
    @Override
    public OAuth1aToken apply(RequestHeaders headers) {
        final String authorization = requireNonNull(headers, "headers").get(header);
        if (Strings.isNullOrEmpty(authorization)) {
            return null;
        }

        final Matcher matcher = AUTHORIZATION_HEADER_PATTERN.matcher(authorization);
        if (!matcher.matches()) {
            logger.warn("Invalid authorization header: " + authorization);
            return null;
        }

        final OAuth1aTokenBuilder builder = OAuth1aToken.builder();
        for (String token : matcher.group("parameters").split(",")) {
            final int sep = token.indexOf('=');
            if (sep == -1 || token.charAt(sep + 1) != '"' || token.charAt(token.length() - 1) != '"') {
                logger.warn("Invalid token: " + token);
                return null;
            }
            final String key = decodeComponent(token.substring(0, sep));
            final String value = decodeComponent(token.substring(sep + 2, token.length() - 1));
            switch (key) {
                case "realm":
                    builder.realm(value);
                    break;
                case "oauth_consumer_key":
                    builder.consumerKey(value);
                    break;
                case "oauth_token":
                    builder.token(value);
                    break;
                case "oauth_signature_method":
                    builder.signatureMethod(value);
                    break;
                case "oauth_signature":
                    builder.signature(value);
                    break;
                case "oauth_timestamp":
                    builder.timestamp(value);
                    break;
                case "oauth_nonce":
                    builder.nonce(value);
                    break;
                case "version":
                    builder.version(value);
                    break;
                default:
                    builder.put(key, value);
            }
        }
        return builder.build();
    }
