 * A fluent builder for creating a new {@link OAuth1aToken}.
 */
public final class OAuth1aTokenBuilder {

    /**
     * The default version value used when the version is not set.
     */
    private static final String DEFAULT_VERSION = "1.0";

    @Nullable
    private String realm;

    @Nullable
    private String consumerKey;

    @Nullable
    private String token;

    @Nullable
    private String signatureMethod;

    @Nullable
    private String signature;

    @Nullable
    private String timestamp;

    @Nullable
    private String nonce;

    @Nullable
    private String version;

    private final ImmutableMap.Builder<String, String> additionals = ImmutableMap.builder();

    OAuth1aTokenBuilder() {}

    /**
     * Sets the realm of the {@link OAuth1aToken}.
     */
    public OAuth1aTokenBuilder realm(String realm) {
        this.realm = requireNonNull(realm, "realm");
        return this;
    }

    /**
     * Sets the consumer key of the {@link OAuth1aToken}.
     */
    public OAuth1aTokenBuilder consumerKey(String consumerKey) {
        this.consumerKey = requireNonNull(consumerKey, "consumerKey");
        return this;
    }

    /**
     * Sets the token of the {@link OAuth1aToken}.
     */
    public OAuth1aTokenBuilder token(String token) {
        this.token = requireNonNull(token, "token");
        return this;
    }

    /**
     * Sets the signature method of the {@link OAuth1aToken}.
     */
    public OAuth1aTokenBuilder signatureMethod(String signatureMethod) {
        this.signatureMethod = requireNonNull(signatureMethod, "signatureMethod");
        return this;
    }

    /**
     * Sets the signature of the {@link OAuth1aToken}.
     */
    public OAuth1aTokenBuilder signature(String signature) {
        this.signature = requireNonNull(signature, "signature");
        return this;
    }

    /**
     * Sets the timestamp of the {@link OAuth1aToken}.
     */
    public OAuth1aTokenBuilder timestamp(String timestamp) {
        this.timestamp = requireNonNull(timestamp, "timestamp");
        return this;
    }

    /**
     * Sets the nonce of the {@link OAuth1aToken}.
     */
    public OAuth1aTokenBuilder nonce(String nonce) {
        this.nonce = requireNonNull(nonce, "nonce");
        return this;
    }

    /**
     * Sets the version of the {@link OAuth1aToken}.
     * If not set, the default value of {@code "1.0"} is used.
     */
    public OAuth1aTokenBuilder version(String version) {
        this.version = requireNonNull(version, "version");
        return this;
    }

    /**
     * Adds an additional (or user-defined) parameter to the {@link OAuth1aToken}.
     */
    public OAuth1aTokenBuilder put(String name, String value) {
        additionals.put(requireNonNull(name, "name"), requireNonNull(value, "value"));
        return this;
    }

    /**
     * Adds the additional (or user-defined) parameters to the {@link OAuth1aToken}.
     */
    public OAuth1aTokenBuilder putAll(Map<? extends String, ? extends String> params) {
        requireNonNull(params, "params");
        for (Map.Entry<? extends String, ? extends String> entry : params.entrySet()) {
            put(entry.getKey(), entry.getValue());
        }
        return this;
    }

    /**
     * Creates a new {@link OAuth1aToken}.
     */
    public OAuth1aToken build() {
        checkArgument(consumerKey != null, "consumerKey is required.");
        checkArgument(token != null, "token is required.");
        checkArgument(signatureMethod != null, "signatureMethod is required.");
        checkArgument(signature != null, "signature is required.");
        checkArgument(timestamp != null, "timestamp is required.");
        checkArgument(nonce != null, "nonce is required.");

        final ImmutableMap.Builder<String, String> builder = ImmutableMap.builder();
        builder.put(OAUTH_CONSUMER_KEY, consumerKey);
        builder.put(OAUTH_TOKEN, token);
        builder.put(OAUTH_SIGNATURE_METHOD, signatureMethod);
        builder.put(OAUTH_SIGNATURE, signature);
        builder.put(OAUTH_TIMESTAMP, timestamp);
        builder.put(OAUTH_NONCE, nonce);
        builder.put(OAUTH_VERSION, version == null ? DEFAULT_VERSION : version);
        if (realm != null) {
            builder.put(REALM, realm);
        }
        builder.putAll(additionals.build());
        return OAuth1aToken.of(builder.build());
    }
}

