package com.linecorp.armeria.common.auth;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

import org.junit.jupiter.api.Test;

import com.google.common.collect.ImmutableMap;

class OAuth1aTokenTest {

    private static OAuth1aToken createToken() {
        return OAuth1aToken.builder()
                           .consumerKey("a")
                           .token("b")
                           .signatureMethod("c")
                           .signature("d")
                           .timestamp("0")
                           .nonce("f")
                           .build();
    }

    @Test
    void getters() {
        final OAuth1aToken token = OAuth1aToken.builder()
                                               .realm("r")
                                               .consumerKey("a")
                                               .token("b")
                                               .signatureMethod("c")
                                               .signature("d")
                                               .timestamp("0")
                                               .nonce("f")
                                               .version("1.0")
                                               .put("x-others", "g")
                                               .putAll(ImmutableMap.of("x-others-2", "h"))
                                               .build();
        assertThat(token.realm()).isEqualTo("r");
        assertThat(token.consumerKey()).isEqualTo("a");
        assertThat(token.token()).isEqualTo("b");
        assertThat(token.signatureMethod()).isEqualTo("c");
        assertThat(token.signature()).isEqualTo("d");
        assertThat(token.timestamp()).isEqualTo("0");
        assertThat(token.nonce()).isEqualTo("f");
        assertThat(token.version()).isEqualTo("1.0");
        assertThat(token.toHeaderValue()).contains(
                "realm=\"r\",oauth_consumer_key=\"a\",oauth_token=\"b\"," +
                "oauth_signature_method=\"c\",oauth_signature=\"d\"," +
                "oauth_timestamp=\"0\",oauth_nonce=\"f\",version=\"1.0\"," +
                "x-others=\"g\",x-others-2=\"h\"");
        assertThat(token.additionals()).containsExactly(
                ImmutableMap.entry("x-others", "g"), ImmutableMap.entry("x-others-2", "h"));
    }

    @Test
    void defaultVersion() {
        assertThat(createToken().version()).isEqualTo("1.0");
    }

    @Test
    void testEquals() {
        final OAuth1aToken token = createToken();
        assertThat(token).isEqualTo(createToken());
        assertThat(token).isNotEqualTo(OAuth1aToken.builder()
                                                   .consumerKey("1")
                                                   .token("2")
                                                   .signatureMethod("3")
                                                   .signature("4")
                                                   .timestamp("5")
                                                   .nonce("6")
                                                   .build());
        assertThat(token).isNotEqualTo(OAuth1aToken.builder()
                                                   .consumerKey("a")
                                                   .token("b")
                                                   .signatureMethod("c")
                                                   .signature("d")
                                                   .timestamp("0")
                                                   .nonce("f")
                                                   .put("x-others", "g")
                                                   .build());
        assertThat(createToken().putAll()).isNotEqualTo(
                OAuth1aToken.builder()
                            .consumerKey("a")
                            .token("b")
                            .signatureMethod("c")
                            .signature("d")
                            .timestamp("0")
                            .nonce("f")
                            .put("x-others", "g")
                            .put("x-others-2", "h")
                            .build());
    }

    @Test
    void missingRequiredParameters() {
        assertThatThrownBy(() -> OAuth1aToken.builder()
                                             .token("b")
                                             .signatureMethod("c")
                                             .signature("d")
                                             .timestamp("0")
                                             .nonce("f")
                                             .build())
                .isInstanceOf(IllegalArgumentException.class)
                .hasMessageContaining("consumerKey is required.");
    }

    @Test
    void invalidTimestamp() {
        assertThatThrownBy(() -> OAuth1aToken.builder()
                                             .consumerKey("a")
                                             .token("b")
                                             .signatureMethod("c")
                                             .signature("d")
                                             .timestamp("invalid")
                                             .nonce("f")
                                             .build())
                .isInstanceOf(IllegalArgumentException.class)
                .hasMessageContaining("Illegal oauth_timestamp value: invalid");
    }
}

