                                          validateHeaders, initialBufferSize),
             new HttpServerResponseEncoder());
    }

    @Override
    public void upgradeFrom(ChannelHandlerContext ctx) {
        ctx.pipeline().remove(this);
    }

    private final class HttpServerRequestDecoder extends HttpRequestDecoder {

        HttpServerRequestDecoder(int maxInitialLineLength, int maxHeaderSize, int maxChunkSize,
                                 boolean validateHeaders, int initialBufferSize) {
            super(maxInitialLineLength, maxHeaderSize, maxChunkSize, validateHeaders, initialBufferSize);
        }

        @Override
        protected HttpMessage createMessage(String[] initialLine) {
            return new NettyHttp1Request(
                    HttpVersion.valueOf(initialLine[2]),
                    HttpMethod.valueOf(initialLine[0]),
                    initialLine[1]);
        }

        @Override
        protected void decode(ChannelHandlerContext ctx, ByteBuf buffer, List<Object> out)
                throws Exception {
            final int size = out.size();
            super.decode(ctx, buffer, out);
            for (int i = size; i < out.size(); i++) {
                final Object obj = out.get(i);
                if (obj instanceof HttpRequest) {
                    // Queue the method so that the encoder can determine the content length.
                    queue.add(((HttpRequest) obj).method());
                }
            }
        }
    }

    private final class HttpServerResponseEncoder extends HttpResponseEncoder {

        private HttpMethod method;

        @Override
        protected void sanitizeHeadersBeforeEncode(HttpResponse msg, boolean isAlwaysEmpty) {
            if (HttpMethod.CONNECT.equals(method) && msg.status().codeClass() == HttpStatusClass.SUCCESS) {
                // Stripping Transfer-Encoding:
                // See https://tools.ietf.org/html/rfc7230#section-3.3.1
                msg.headers().remove(HttpHeaderNames.TRANSFER_ENCODING);
                return;
            }
            super.sanitizeHeadersBeforeEncode(msg, isAlwaysEmpty);
        }

        @Override
        protected boolean isContentAlwaysEmpty(HttpResponse msg) {
            // Get the HttpMethod the client used for this response.
            //
            // If it is a TRACE or CONNECT, the response might have a body.
            // https://tools.ietf.org/html/rfc7230#section-3.3.3
            //
            // When it is not TRACE or CONNECT, the response has a body only if it is not a response
            // to a HEAD request.
            //
            // From the RFC, a response to a HEAD request is not allowed to have a body.
            method = queue.poll();
            return HttpMethod.HEAD.equals(method) || super.isContentAlwaysEmpty(msg);
        }
    }
