private static void purgeHttp1OnlyHeaders(RequestHeadersBuilder out) {
    // Remove the connection-specific headers first because they must not be
    // copied when converting the HTTP/1 headers to HTTP/2 headers.
    final CharSequenceMap connectionBlacklist =
            toLowercaseMap(out.valueIterator(HttpHeaderNames.CONNECTION), 8);
    for (AsciiString name : connectionBlacklist.names()) {
        out.remove(name);
