            final int port = ((InetSocketAddress) ctx.channel().localAddress()).getPort();
            out.add(HttpHeaderNames.AUTHORITY, defaultHostname + ':' + port);
        }

        // Add the HTTP headers which have not been consumed above
        toArmeria(inHeaders, out);
        return out.build();
