        if (!isOriginForm(requestTargetUri) && !isAsteriskForm(requestTargetUri)) {
            // Attempt to take from HOST header before taking from the request-line
            final String host = inHeaders.getAsString(HttpHeaderNames.HOST);
            addHttp2Authority(host == null || host.isEmpty() ? requestTargetUri.getAuthority() : host, out);
        }

        if (out.authority() == null) {
            final String defaultHostname = cfg.defaultVirtualHost().defaultHostname();
            final int port = ((InetSocketAddress) ctx.channel().localAddress()).getPort();
            out.add(HttpHeaderNames.AUTHORITY, defaultHostname + ':' + port);
        }

        // Add the HTTP headers which have not been consumed above
        toArmeria(inHeaders, out);
        return out.build();
    }

    /**
     * Converts the headers of the given Netty HTTP/1.x request into Armeria HTTP/2 headers by filling
     * the specified {@code out}, which must be the {@link RequestHeadersBuilder} that backs the headers
     * of the given {@code in}. Because the headers are built directly into the specified {@code out},
     * this method does not copy the headers unlike {@link #toArmeria(ChannelHandlerContext, HttpRequest,
     * ServerConfig)}.
     */
    public static RequestHeaders toArmeria(ChannelHandlerContext ctx, HttpRequest in,
                                           RequestHeadersBuilder out,
                                           ServerConfig cfg) throws URISyntaxException {
        final URI requestTargetUri = toUri(in);

        out.set(HttpHeaderNames.METHOD, in.method().name());
        out.set(HttpHeaderNames.PATH, toHttp2Path(requestTargetUri));

        addHttp2Scheme(in.headers(), requestTargetUri, out);

        if (!isOriginForm(requestTargetUri) && !isAsteriskForm(requestTargetUri)) {
            // Attempt to take from HOST header before taking from the request-line
            final String host = in.headers().getAsString(HttpHeaderNames.HOST);
            addHttp2Authority(host == null || host.isEmpty() ? requestTargetUri.getAuthority() : host, out);
        }

        if (out.authority() == null) {
            final String defaultHostname = cfg.defaultVirtualHost().defaultHostname();
            final int port = ((InetSocketAddress) ctx.channel().localAddress()).getPort();
            out.add(HttpHeaderNames.AUTHORITY, defaultHostname + ':' + port);
        }

        // Remove or adapt the HTTP/1-only headers which have been stored in the specified {@code out}
        // while decoding the request.
        purgeHttp1OnlyHeaders(out);
        return out.build();
    }

    /**
     * Removes or adapts the HTTP/1-only headers from the specified {@code out} which is being converted
     * into an HTTP/2 {@link RequestHeaders}.
     */
    private static void purgeHttp1OnlyHeaders(RequestHeadersBuilder out) {
        // Remove the headers specified in the 'Connection' header and the 'Connection' header itself.
        final CharSequenceMap connectionBlacklist =
                toLowercaseMap(out.valueIterator(HttpHeaderNames.CONNECTION), 8);
        for (AsciiString name : connectionBlacklist.names()) {
            out.remove(name);
        }
        out.remove(HttpHeaderNames.CONNECTION);

        out.remove(HEADER_NAME_KEEP_ALIVE);
        out.remove(HEADER_NAME_PROXY_CONNECTION);
        out.remove(HttpHeaderNames.TRANSFER_ENCODING);
        out.remove(HttpHeaderNames.HOST);
        out.remove(HttpHeaderNames.UPGRADE);
        out.remove(ExtensionHeaderNames.STREAM_ID.text());
        out.remove(ExtensionHeaderNames.SCHEME.text());
        out.remove(ExtensionHeaderNames.PATH.text());

        // https://tools.ietf.org/html/rfc7540#section-8.1.2.2 makes a special exception for TE
        final List<String> teValues = out.getAll(HttpHeaderNames.TE);
        if (!teValues.isEmpty()) {
            out.remove(HttpHeaderNames.TE);
            for (String teValue : teValues) {
                toHttp2HeadersFilterTE(teValue, out);
            }
        }

        // Cookies must be concatenated into a single octet string.
        // https://tools.ietf.org/html/rfc7540#section-8.1.2.5
        final List<String> cookies = out.getAll(HttpHeaderNames.COOKIE);
        if (!cookies.isEmpty()) {
            out.remove(HttpHeaderNames.COOKIE);
            final StringJoiner cookieJoiner = new StringJoiner(COOKIE_SEPARATOR);
            for (String cookie : cookies) {
                COOKIE_SPLITTER.split(cookie).forEach(cookieJoiner::add);
            }
            if (cookieJoiner.length() != 0) {
                out.add(HttpHeaderNames.COOKIE, cookieJoiner.toString());
            }
        }
    }

    /**
     * Adapted from {@link #toHttp2HeadersFilterTE(Entry, HttpHeadersBuilder)} for a single value.
     */
    private static void toHttp2HeadersFilterTE(String teValue, HttpHeadersBuilder out) {
        if (AsciiString.indexOf(teValue, ',', 0) == -1) {
            if (AsciiString.contentEqualsIgnoreCase(AsciiString.trim(teValue),
                                                    HttpHeaderValues.TRAILERS)) {
                out.add(HttpHeaderNames.TE, HttpHeaderValues.TRAILERS.toString());
            }
        } else {
            final List<CharSequence> split = StringUtil.unescapeCsvFields(teValue);
            for (CharSequence subValue : split) {
                if (AsciiString.contentEqualsIgnoreCase(AsciiString.trim(subValue),
                                                        HttpHeaderValues.TRAILERS)) {
                    out.add(HttpHeaderNames.TE, HttpHeaderValues.TRAILERS.toString());
                    break;
                }
            }
        }
    }

