                filterTEValue(teValue, out);
            }
        }

        // Cookies must be concatenated into a single octet string.
        // https://tools.ietf.org/html/rfc7540#section-8.1.2.5
        final List<String> cookies = out.getAll(HttpHeaderNames.COOKIE);
        if (!cookies.isEmpty()) {
