package com.linecorp.armeria.server;

import static org.assertj.core.api.Assertions.assertThat;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

import java.net.InetSocketAddress;
import java.net.URISyntaxException;
import java.nio.charset.StandardCharsets;
import java.util.Iterator;
import java.util.Map.Entry;

import org.junit.jupiter.api.Test;

import com.linecorp.armeria.common.HttpHeaderNames;
import com.linecorp.armeria.common.HttpMethod;
import com.linecorp.armeria.common.HttpResponse;
import com.linecorp.armeria.common.HttpStatus;
import com.linecorp.armeria.common.RequestHeaders;
import com.linecorp.armeria.common.RequestHeadersBuilder;
import com.linecorp.armeria.internal.common.ArmeriaHttpUtil;

import io.netty.buffer.Unpooled;
import io.netty.channel.Channel;
import io.netty.channel.ChannelHandlerContext;
import io.netty.channel.embedded.EmbeddedChannel;
import io.netty.handler.codec.http.HttpMethod as NettyHttpMethod;
import io.netty.handler.codec.http.HttpVersion;
import io.netty.handler.codec.http2.HttpConversionUtil.ExtensionHeaderNames;
import io.netty.util.AsciiString;

class NettyHttp1RequestTest {

    @Test
    void delegatesMethods() {
        final NettyHttp1Request request =
                new NettyHttp1Request(HttpVersion.HTTP_1_1, NettyHttpMethod.POST, "/index.html");
        final NettyHttp1Headers headers = (NettyHttp1Headers) request.headers();

        assertThat(headers.isEmpty()).isTrue();
        headers.add("User-Agent", "curl/7.68.0");
        headers.add("X-Foo", "bar");
        headers.add("X-Foo", "qux");

        assertThat(headers.isEmpty()).isFalse();
        assertThat(headers.size()).isEqualTo(2);
        assertThat(headers.get("user-agent")).isEqualTo("curl/7.68.0");
        assertThat(headers.contains("x-foo")).isTrue();
        assertThat(headers.getAll("x-foo")).containsExactly("bar", "qux");
        assertThat(headers.getInt("content-length", 42)).isEqualTo(42);
        assertThat(headers.getInt("content-length")).isNull();
        assertThat(headers.getShort("x-foo", (short) 3)).isEqualTo((short) 3);

        final Iterator<Entry<CharSequence, CharSequence>> i = headers.iteratorCharSequence();
        while (i.hasNext()) {
            final Entry<CharSequence, CharSequence> e = i.next();
            assertThat(e.getKey()).isNotEqualTo(new AsciiString(""));
        }

        final RequestHeadersBuilder delegate = headers.delegate();
        assertThat(delegate.get(HttpHeaderNames.METHOD)).isEqualTo("POST");
        assertThat(delegate.get(HttpHeaderNames.PATH)).isEqualTo("/index.html");

        assertThat(headers.remove("x-foo")).isSameAs(headers);
        assertThat(headers.contains("x-foo")).isFalse();
        headers.clear();
        assertThat(headers.isEmpty()).isTrue();
    }

    @Test
    void setMethodAndSetUriKeepPseudoHeadersInSync() {
        final NettyHttp1Request request =
                new NettyHttp1Request(HttpVersion.HTTP_1_1, NettyHttpMethod.POST, "/old");
        final RequestHeadersBuilder delegate = ((NettyHttp1Headers) request.headers()).delegate();

        request.setMethod(NettyHttpMethod.PUT);
        request.setUri("/new");
        assertThat(request.method()).isEqualTo(NettyHttpMethod.PUT);
        assertThat(request.uri()).isEqualTo("/new");
        assertThat(delegate.get(HttpHeaderNames.METHOD)).isEqualTo("PUT");
        assertThat(delegate.get(HttpHeaderNames.PATH)).isEqualTo("/new");
    }

    @Test
    void toArmeriaOriginFormRequest() throws URISyntaxException {
        final NettyHttp1Request request = decode("POST /upload?q=1 HTTP/1.1\r\n" +
                                                 "Host: example.com\r\n" +
                                                 "Connection: keep-alive, Upgrade\r\n" +
                                                 "Upgrade: h2c\r\n" +
                                                 "Transfer-Encoding: chunked\r\n" +
                                                 "Cookie: a=b\r\n" +
                                                 "Cookie: c=d\r\n" +
                                                 "TE: trailers\r\n" +
                                                 "x-custom: Value\r\n" +
                                                 "\r\n");
        final RequestHeaders headers = toArmeria(request);

        assertThat(headers.method()).isEqualTo(HttpMethod.POST);
        assertThat(headers.path()).isEqualTo("/upload?q=1");
        assertThat(headers.scheme()).isEqualTo("http");
        assertThat(headers.authority()).isEqualTo("foo:36462");

        // The HTTP/1-specific headers must be removed or adapted.
        assertThat(headers.contains(HttpHeaderNames.HOST)).isFalse();
        assertThat(headers.contains(HttpHeaderNames.CONNECTION)).isFalse();
        assertThat(headers.contains(ArmeriaHttpUtil.HEADER_NAME_KEEP_ALIVE)).isFalse();
        assertThat(headers.contains(ArmeriaHttpUtil.HEADER_NAME_PROXY_CONNECTION)).isFalse();
        assertThat(headers.contains(HttpHeaderNames.TRANSFER_ENCODING)).isFalse();
        assertThat(headers.contains(HttpHeaderNames.UPGRADE)).isFalse();
        // The header specified in the 'Connection' header must be removed as well.
        assertThat(headers.contains(HttpHeaderNames.KEEP_ALIVE)).isFalse();

        // The cookies must be concatenated into a single octet string.
        assertThat(headers.getAll(HttpHeaderNames.COOKIE)).containsExactly("a=b; c=d");
        // TE: trailers is the only permitted TE header value.
        assertThat(headers.get(HttpHeaderNames.TE)).isEqualTo("trailers");

        assertThat(headers.get("x-custom")).isEqualTo("Value");
    }

    @Test
    void toArmeriaAbsoluteFormRequest() throws URISyntaxException {
        final NettyHttp1Request request = decode("GET http://example.com:8080/index.html HTTP/1.1\r\n" +
                                                 "Host: example.com:8080\r\n" +
                                                 "Connection: close\r\n" +
                                                 "TE: gzip\r\n" +
                                                 "\r\n");
        final RequestHeaders headers = toArmeria(request);

        assertThat(headers.method()).isEqualTo(HttpMethod.GET);
        assertThat(headers.path()).isEqualTo("/index.html");
        assertThat(headers.scheme()).isEqualTo("http");
        // The authority must be taken from the 'Host' header.
        assertThat(headers.authority()).isEqualTo("example.com:8080");

        assertThat(headers.contains(HttpHeaderNames.CONNECTION)).isFalse();
        // The TE value other than 'trailers' must be removed.
        assertThat(headers.contains(HttpHeaderNames.TE)).isFalse();
        assertThat(headers.contains(HttpHeaderNames.HOST)).isFalse();
    }

    private static NettyHttp1Request decode(String rawRequest) {
        final EmbeddedChannel channel = new EmbeddedChannel(new HttpServerCodec(4096, 8192, 8192));
        try {
            channel.writeInbound(Unpooled.copiedBuffer(rawRequest, StandardCharsets.US_ASCII));
            final Object msg = channel.readInbound();
            assertThat(msg).isInstanceOf(NettyHttp1Request.class);
            return (NettyHttp1Request) msg;
        } finally {
            channel.finishAndReleaseAll();
        }
    }

    private static RequestHeaders toArmeria(NettyHttp1Request request) throws URISyntaxException {
        final InetSocketAddress socketAddress = new InetSocketAddress(36462);
        final Channel channel = mock(Channel.class);
        when(channel.localAddress()).thenReturn(socketAddress);

        final ChannelHandlerContext ctx = mock(ChannelHandlerContext.class);
        when(ctx.channel()).thenReturn(channel);

        // The scheme is set to the 'Http2-Scheme' extension header by Http1RequestDecoder.
        request.headers().set(ExtensionHeaderNames.SCHEME.text(), "http");

        final ServerConfig cfg = Server.builder()
                                       .defaultHostname("foo")
                                       .service("/", (c, req) -> HttpResponse.of(HttpStatus.OK))
                                       .build()
                                       .config();
        return ArmeriaHttpUtil.toArmeria(
                ctx, request, ((NettyHttp1Headers) request.headers()).delegate(), cfg);
    }
}

