private Endpoint createEndpoint(Service service, Pod pod, int nodePort) {
    final PodSpec podSpec = pod.getSpec();
    if (podSpec == null || podSpec.getNodeName() == null) {
        return null;
    }
    final PodStatus podStatus = pod.getStatus();
    if (podStatus == null || !"Running".equals(podStatus.getPhase())) {
