    final Node node = nodesByName.get(podSpec.getNodeName());
    if (node == null) {
        return null;
    }
    final String address = nodeAddress(node, nodeAddressType);
    if (address == null) {
        return null;
    }
    return Endpoint.of(address, nodePort);
}
