                .withNewSpec().endSpec()
                .withNewStatus().addNewAddress().withType("InternalIP").withAddress("10.0.14.12").endAddress().endStatus()
                .build();
        Node createdNode = client.nodes().create(node);
        System.out.println("NODE CREATED: " + createdNode.getMetadata().getName());

        // 2) list nodes
