                nodeLatches.countDown();
            }
            public void onClose(WatcherException cause) {
                System.out.println("NODE WATCH CLOSED: " + cause);
            }
        }));
        System.out.println("node watch established: " + (nodeWatch.get() != null));

        // 4) create service
        Service service = new ServiceBuilder()
                .withNewMetadata().withName("web").withNamespace("default")
                    .withLabels(Collections.singletonMap("app", "web")).endMetadata()
                .withNewSpec()
