        System.out.println("SERVICE CREATED: " + svc.getMetadata().getName() + " nodePort="
                + svc.getSpec().getPorts().get(0).getNodePort());

        // 5) create pod
        Pod pod = new PodBuilder()
                .withNewMetadata().withName("pod1").withNamespace("default")
                    .withLabels(Collections.singletonMap("app", "web")).endMetadata()
                .withNewSpec().withNodeName("node1").endSpec()
                .withNewStatus().withPhase("Running").endStatus()
                .build();
        Pod createdPod = client.pods().inNamespace("default").create(pod);
        System.out.println("POD CREATED: " + createdPod.getMetadata().getName());

        // 6) watch pods
        CountDownLatch podLatch = new CountDownLatch(2);
        client.pods().inNamespace("default").watch(new Watcher<Pod>() {
            public void eventReceived(Action action, Pod resource) {
                System.out.println("POD EVENT: " + action + " " + resource.getMetadata().getName());
                podLatch.countDown();
            }
            public void onClose(WatcherException cause) {
                System.out.println("POD WATCH CLOSED: " + cause);
            }
        });

        // 7) service watch
        client.services().inNamespace("default").watch(new Watcher<Service>() {
            public void eventReceived(Action action, Service resource) {
                System.out.println("SERVICE EVENT: " + action + " " + resource.getMetadata().getName());
            }
            public void onClose(WatcherException cause) {
                System.out.println("SERVICE WATCH CLOSED: " + cause);
            }
        });

