package com.linecorp.armeria.client.endpoint;

import static java.util.Objects.requireNonNull;

import com.linecorp.armeria.client.retry.Backoff;

/**
 * A skeletal builder implementation for {@link DynamicEndpointGroup} and its subtypes.
 */
public abstract class AbstractDynamicEndpointGroupBuilder {

    private static final Backoff DEFAULT_RETRY_BACKOFF = Backoff.fixed(1000).withMaxAttempts(5);

    private Backoff retryBackoff = DEFAULT_RETRY_BACKOFF;
    private EndpointSelectionStrategy selectionStrategy = EndpointSelectionStrategy.weightedRoundRobin();

    /**
     * Creates a new instance.
     */
    protected AbstractDynamicEndpointGroupBuilder() {}

    /**
     * Sets the {@link Backoff} which determines how much delay should be inserted between the attempts to
     * (re)connect to the remote service. {@link Backoff#fixed(long)} {@code 1000} milliseconds with
     * {@code maxAttempts} of {@code 5} is used by default.
     */
    public AbstractDynamicEndpointGroupBuilder retryBackoff(Backoff retryBackoff) {
        this.retryBackoff = requireNonNull(retryBackoff, "retryBackoff");
        return this;
    }

    /**
     * Sets the {@link EndpointSelectionStrategy} which determines the order of {@link Endpoint}s to be
     * selected. {@link EndpointSelectionStrategy#weightedRoundRobin()} is used by default.
     */
    public AbstractDynamicEndpointGroupBuilder selectionStrategy(EndpointSelectionStrategy selectionStrategy) {
        this.selectionStrategy = requireNonNull(selectionStrategy, "selectionStrategy");
        return this;
    }

    /**
     * Returns the configured {@link Backoff}.
     */
    protected final Backoff retryBackoff() {
        return retryBackoff;
    }

    /**
     * Returns the configured {@link EndpointSelectionStrategy}.
     */
    protected final EndpointSelectionStrategy selectionStrategy() {
        return selectionStrategy;
    }
}

