package com.linecorp.armeria.client.kubernetes.endpoints;

import static java.util.Objects.requireNonNull;

import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ThreadFactory;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.concurrent.atomic.AtomicInteger;

import javax.annotation.Nullable;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import com.google.common.collect.ImmutableList;

import com.linecorp.armeria.client.Endpoint;
import com.linecorp.armeria.client.endpoint.DynamicEndpointGroup;
import com.linecorp.armeria.client.endpoint.EndpointSelectionStrategy;
import com.linecorp.armeria.client.retry.Backoff;

import io.fabric8.kubernetes.api.model.Node;
import io.fabric8.kubernetes.api.model.NodeAddress;
import io.fabric8.kubernetes.api.model.NodeList;
import io.fabric8.kubernetes.api.model.NodeStatus;
import io.fabric8.kubernetes.api.model.Pod;
import io.fabric8.kubernetes.api.model.PodList;
import io.fabric8.kubernetes.api.model.PodSpec;
import io.fabric8.kubernetes.api.model.PodStatus;
import io.fabric8.kubernetes.api.model.Service;
import io.fabric8.kubernetes.api.model.ServiceList;
import io.fabric8.kubernetes.api.model.ServicePort;
import io.fabric8.kubernetes.api.model.ServiceSpec;
import io.fabric8.kubernetes.client.KubernetesClient;
import io.fabric8.kubernetes.client.Watch;
import io.fabric8.kubernetes.client.Watcher;
import io.fabric8.kubernetes.client.WatcherException;

/**
 * A dynamic {@link DynamicEndpointGroup} which discovers its {@link Endpoint}s from the services and pods
 * of a Kubernetes cluster. The endpoints are built from the {@code InternalIP} address of the nodes that host
 * the pods backing the target service and the {@code nodePort} exposed by the target service, so that the
 * traffic can be sent directly to the pods without going through a load balancer or an ingress.
 */
public final class KubernetesEndpointGroup extends DynamicEndpointGroup {

    private static final Logger logger = LoggerFactory.getLogger(KubernetesEndpointGroup.class);

    private static final String DEFAULT_NAMESPACE = "default";
    private static final String RUNNING_PHASE = "Running";

    private final KubernetesClient client;
    private final String serviceName;
    private final String namespace;
    @Nullable
    private final String portName;
    private final String nodeAddressType;
    private final Backoff retryBackoff;
    private final boolean closeClient;

    private final Map<String, Node> nodes = new ConcurrentHashMap<>();
    private final Map<String, Pod> pods = new ConcurrentHashMap<>();
    private final ScheduledExecutorService reconnectExecutor;

    private final ServiceWatcher serviceWatcher;
    private final NodeWatcher nodeWatcher;
    private final PodWatcher podWatcher;

    private volatile Service service;

    KubernetesEndpointGroup(KubernetesClient client, boolean closeClient, String serviceName,
                            String namespace, @Nullable String portName, String nodeAddressType,
                            Backoff retryBackoff, EndpointSelectionStrategy selectionStrategy) {
        super(selectionStrategy);
        this.client = requireNonNull(client, "client");
        this.closeClient = closeClient;
        this.serviceName = requireNonNull(serviceName, "serviceName");
        this.namespace = requireNonNull(namespace, "namespace");
        this.portName = portName;
        this.nodeAddressType = requireNonNull(nodeAddressType, "nodeAddressType");
        this.retryBackoff = requireNonNull(retryBackoff, "retryBackoff");

        reconnectExecutor = Executors.newSingleThreadScheduledExecutor(new ThreadFactory() {
            @Override
            public Thread newThread(Runnable r) {
                final Thread thread = new Thread(r, "kubernetes-endpoint-group-watch");
                thread.setDaemon(true);
                return thread;
            }
        });

        serviceWatcher = new ServiceWatcher();
        nodeWatcher = new NodeWatcher();
        podWatcher = new PodWatcher();

        // Populate the initial state and start watching the resources.
        serviceWatcher.initialize();
        nodeWatcher.initialize();
        podWatcher.initialize();
    }

    private void updateEndpoints() {
        final Service service = this.service;
        if (service == null) {
            setEndpoints(ImmutableList.of());
            return;
        }
        final ServiceSpec spec = service.getSpec();
        final List<ServicePort> ports = spec == null ? null : spec.getPorts();
        if (ports == null || ports.isEmpty()) {
            setEndpoints(ImmutableList.of());
            return;
        }

        final Set<Endpoint> newEndpoints = new HashSet<>();
        for (ServicePort port : ports) {
            if (portName != null && !portName.equals(port.getName())) {
                continue;
            }
            final Integer nodePort = port.getNodePort();
            if (nodePort == null || nodePort <= 0) {
                continue;
            }
            for (Pod pod : pods.values()) {
                final Endpoint endpoint = toEndpoint(service, pod, nodePort);
                if (endpoint != null) {
                    newEndpoints.add(endpoint);
                }
            }
        }
        setEndpoints(newEndpoints);
    }

    @Nullable
    private Endpoint toEndpoint(Service service, Pod pod, int nodePort) {
        final PodSpec podSpec = pod.getSpec();
        final String nodeName = podSpec == null ? null : podSpec.getNodeName();
        if (nodeName == null) {
            return null;
        }
        final PodStatus podStatus = pod.getStatus();
        if (podStatus == null || !RUNNING_PHASE.equals(podStatus.getPhase())) {
            return null;
        }
        if (!matchesServiceSelector(service, pod)) {
            return null;
        }
        final Node node = nodes.get(nodeName);
        if (node == null) {
            return null;
        }
        final String address = nodeAddress(node);
        if (address == null) {
            return null;
        }
        return Endpoint.of(address, nodePort);
    }

    private static boolean matchesServiceSelector(Service service, Pod pod) {
        final ServiceSpec spec = service.getSpec();
        if (spec == null) {
            return false;
        }
        final Map<String, String> selector = spec.getSelector();
        if (selector == null || selector.isEmpty()) {
            // If the selector is empty, all pods are considered to back the service.
            return true;
        }
        final Map<String, String> labels =
                pod.getMetadata() == null ? null : pod.getMetadata().getLabels();
        if (labels == null || labels.isEmpty()) {
            return false;
        }
        for (Map.Entry<String, String> entry : selector.entrySet()) {
            if (!entry.getValue().equals(labels.get(entry.getKey()))) {
                return false;
            }
        }
        return true;
    }

    @Nullable
    private String nodeAddress(Node node) {
        final NodeStatus status = node.getStatus();
        if (status == null) {
            return null;
        }
        final List<NodeAddress> addresses = status.getAddresses();
        if (addresses == null || addresses.isEmpty()) {
            return null;
        }
        for (NodeAddress address : addresses) {
            if (nodeAddressType.equals(address.getType())) {
                return address.getAddress();
            }
        }
        return null;
    }

    private static String podKey(Pod pod) {
        final String name = pod.getMetadata() == null ? null : pod.getMetadata().getName();
        return String.valueOf(name);
    }

    private static String nodeKey(Node node) {
        return podKey(node);
    }

    @Override
    protected void doCloseAsync(CompletableFuture<?> future) {
        serviceWatcher.closeWatch();
        nodeWatcher.closeWatch();
        podWatcher.closeWatch();
        reconnectExecutor.shutdownNow();
        if (closeClient) {
            try {
                client.close();
            } catch (Exception e) {
                logger.warn("Failed to close the Kubernetes client.", e);
            }
        }
        future.complete(null);
    }

    private abstract class AbstractWatcher<T> implements Watcher<T> {

        private final AtomicBoolean reconnecting = new AtomicBoolean();
        private final AtomicInteger reconnectAttempts = new AtomicInteger();

        @Nullable
        private volatile Watch watch;

        @Override
        public final void eventReceived(Action action, T resource) {
            if (action == Action.ERROR) {
                logger.warn("Received an ERROR event while watching {}. Reconnecting...", name());
                reconnect();
                return;
            }
            onEvent(action, resource);
        }

        @Override
        public final void onClose(@Nullable WatcherException cause) {
            if (cause != null) {
                logger.debug("The watch on {} has been closed unexpectedly. cause: {}",
                             name(), cause.getMessage());
            }
            reconnect();
        }

        protected abstract void onEvent(Action action, T resource);

        protected abstract Watch startWatch();

        protected abstract String name();

        final void initialize() {
            try {
                watch = startWatch();
            } catch (Exception e) {
                logger.warn("Failed to start a watch on {}; a reconnection attempt will be made.", name(), e);
                reconnect();
            }
        }

        final void closeWatch() {
            final Watch watch = this.watch;
            if (watch != null) {
                try {
                    watch.close();
                } catch (Exception ignored) {
                    // Ignore the exception because the watch is being closed.
                }
            }
        }

        final void reconnect() {
            if (isClosing() || isClosed()) {
                return;
            }
            if (!reconnecting.compareAndSet(false, true)) {
                return;
            }
            closeWatch();
            scheduleNextAttempt();
        }

        private void scheduleNextAttempt() {
            final long delay = retryBackoff.nextDelayMillis(reconnectAttempts.incrementAndGet());
            if (delay < 0) {
                logger.warn("Giving up reconnecting to the watch on {} after {} attempts.",
                            name(), reconnectAttempts.get());
                reconnecting.set(false);
                return;
            }
            reconnectExecutor.schedule(this::connect, delay, TimeUnit.MILLISECONDS);
        }

        private void connect() {
            try {
                if (isClosing() || isClosed()) {
                    reconnecting.set(false);
                    return;
                }
                final Watch watch = startWatch();
                this.watch = watch;
                if (isClosing() || isClosed()) {
                    watch.close();
                }
                reconnectAttempts.set(0);
            } catch (Exception e) {
                logger.warn("Failed to reconnect to the watch on {}; will retry.", name(), e);
                scheduleNextAttempt();
            } finally {
                reconnecting.set(false);
            }
        }
    }

    private final class ServiceWatcher extends AbstractWatcher<Service> {

        @Override
        protected void onEvent(Action action, Service service) {
            if (service.getMetadata() == null || !serviceName.equals(service.getMetadata().getName())) {
                return;
            }
            if (action == Action.DELETED) {
                KubernetesEndpointGroup.this.service = null;
            } else {
                KubernetesEndpointGroup.this.service = service;
            }
            updateEndpoints();
        }

        @Override
        protected Watch startWatch() {
            reloadServices();
            return client.services().inNamespace(namespace).watch(this);
        }

        @Override
        protected String name() {
            return "services";
        }
    }

    private final class NodeWatcher extends AbstractWatcher<Node> {

        @Override
        protected void onEvent(Action action, Node node) {
            final String name = nodeKey(node);
            if (name.isEmpty()) {
                return;
            }
            if (action == Action.DELETED) {
                nodes.remove(name);
            } else {
                nodes.put(name, node);
            }
            updateEndpoints();
        }

        @Override
        protected Watch startWatch() {
            final NodeList nodeList = client.nodes().list();
            nodes.clear();
            for (Node node : nodeList.getItems()) {
                final String name = nodeKey(node);
                if (!name.isEmpty()) {
                    nodes.put(name, node);
                }
            }
            return client.nodes().watch(this);
        }

        @Override
        protected String name() {
            return "nodes";
        }
    }

    private final class PodWatcher extends AbstractWatcher<Pod> {

        @Override
        protected void onEvent(Action action, Pod pod) {
            final String key = podKey(pod);
            if (key.isEmpty()) {
                return;
            }
            if (action == Action.DELETED) {
                pods.remove(key);
            } else {
                pods.put(key, pod);
            }
            updateEndpoints();
        }

        @Override
        protected Watch startWatch() {
            final PodList podList = client.pods().inNamespace(namespace).list();
            pods.clear();
            for (Pod pod : podList.getItems()) {
                final String key = podKey(pod);
                if (!key.isEmpty()) {
                    pods.put(key, pod);
                }
            }
            return client.pods().inNamespace(namespace).watch(this);
        }

        @Override
        protected String name() {
            return "pods";
        }
    }
}

