     * ports without a matching name are ignored and the first port is used. Setting this property is useful
     * only when the target service exposes multiple ports.
     */
    public KubernetesEndpointGroupBuilder portName(String portName) {
        this.portName = requireNonNull(portName, "portName");
        return this;
    }

    /**
     * Sets the type of the node address to use for building the {@link com.linecorp.armeria.client.Endpoint}s,
