            createService(client(), "web", NAMESPACE, newPort("http", 80, 32111), WEB_SELECTOR);
            createPod(client(), "pod-1", NAMESPACE, "web", "node1");

            await().untilAsserted(() -> assertThat(group.endpoints())
                    .containsExactly(Endpoint.of("10.0.14.12", 32111)));
        }
    }

    @Test
    @Timeout(30)
    void filteringNodeAddress() {
        final Node node = createNode(client(), "node1",
                                     ImmutableMap.of("InternalIP", "10.0.14.12",
                                                     "ExternalIP", "203.0.113.10"));
        createService(client(), "web", NAMESPACE, newPort("http", 80, 32111), WEB_SELECTOR);
        createPod(client(), "pod-1", NAMESPACE, "web", "node1");

        // The InternalIP address is used by default.
        try (KubernetesEndpointGroup group = KubernetesEndpointGroup.builder(client())
                .namespace(NAMESPACE)
                .serviceName("web")
                .nodeAddressType("InternalIP")
                .build()) {
            await().untilAsserted(() -> assertThat(group.endpoints())
                    .containsExactly(Endpoint.of("10.0.14.12", 32111)));
        }

        // The ExternalIP address is used when specified.
        try (KubernetesEndpointGroup group = KubernetesEndpointGroup.builder(client())
                .namespace(NAMESPACE)
                .serviceName("web")
                .nodeAddressType("ExternalIP")
                .build()) {
            await().untilAsserted(() -> assertThat(group.endpoints())
                    .containsExactly(Endpoint.of("203.0.113.10", 32111)));
        }
    }

    private static Node createNode(KubernetesClient client, String name, String addressType,
                                   String address) {
        final Node node = new NodeBuilder()
                .withNewMetadata().withName(name).endMetadata()
                .withNewSpec().endSpec()
                .withNewStatus()
                .addNewAddress().withType(addressType).withAddress(address).endAddress()
                .endStatus()
                .build();
        client.nodes().create(node);
        return node;
    }

    private static Node createNode(KubernetesClient client, String name, Map<String, String> addresses) {
        final NodeBuilder nodeBuilder = new NodeBuilder()
                .withNewMetadata().withName(name).endMetadata()
                .withNewSpec().endSpec()
                .withNewStatus();
        for (Map.Entry<String, String> entry : addresses.entrySet()) {
            nodeBuilder.addNewAddress().withType(entry.getKey()).withAddress(entry.getValue()).endAddress();
        }
        final Node node = nodeBuilder.endStatus().build();
        client.nodes().create(node);
        return node;
    }

    private static Service createService(KubernetesClient client, String name, String namespace,
                                         List<ServicePort> ports, Map<String, String> selector) {
        final Service service = new ServiceBuilder()
                .withNewMetadata().withName(name).withNamespace(namespace)
                .withLabels(selector)
                .endMetadata()
                .withNewSpec()
                .withType("NodePort")
                .withSelector(selector)
                .withPorts(ports)
                .endSpec()
                .build();
        client.services().inNamespace(namespace).create(service);
        return service;
    }

    private static Pod createPod(KubernetesClient client, String name, String namespace, String app,
                                 String nodeName) {
        final Pod pod = new PodBuilder()
                .withNewMetadata().withName(name).withNamespace(namespace)
                .withLabels(ImmutableMap.of("app", app))
                .endMetadata()
                .withNewSpec().withNodeName(nodeName).endSpec()
                .withNewStatus().withPhase("Running").endStatus()
                .build();
        client.pods().inNamespace(namespace).create(pod);
        return pod;
    }

    private static ServicePort newPort(String name, int port, int nodePort) {
        return new ServicePortBuilder()
                .withName(name)
                .withPort(port)
                .withNodePort(nodePort)
                .withNewTargetPort(port)
                .build();
    }
}

