package com.linecorp.armeria.client.kubernetes.endpoints;

import static org.assertj.core.api.Assertions.assertThat;
import static org.junit.jupiter.api.Assumptions.assumeTrue;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.Timeout;

import com.linecorp.armeria.client.Endpoint;

import io.fabric8.kubernetes.client.DefaultKubernetesClient;
import io.fabric8.kubernetes.client.KubernetesClient;

/**
 * An integration test for {@link KubernetesEndpointGroup} that runs against a real Kubernetes cluster.
 * It is skipped automatically unless a Kubernetes cluster is available, i.e. either the
 * {@code KUBECONFIG} environment variable is set or the cluster config is found in
 * {@code ~/.kube/config}.
 *
 * <p>To run it against a real cluster, ensure a service of type {@code NodePort} or
 * {@code LoadBalancer} exists in the cluster and specify its name using the
 * {@code ARMEIA_KUBERNETES_SERVICE_NAME} system property. The tests also require the Kubernetes client
 * to have the permissions to watch {@code services}, {@code nodes} and {@code pods}.
 */
class KubernetesEndpointGroupIntegrationTest {

    @Test
    @Timeout(30)
    void endpointsInOneNode() {
        assumeTrue(isKubernetesAvailable(),
                   "Kubernetes cluster is not available; skipping the integration test");
        final String serviceName = System.getProperty("ARMEIA_KUBERNETES_SERVICE_NAME", "web");
        final String namespace = System.getProperty("ARMEIA_KUBERNETES_NAMESPACE", "default");

        try (KubernetesClient client = new DefaultKubernetesClient();
             KubernetesEndpointGroup group = KubernetesEndpointGroup.builder(client)
                     .namespace(namespace)
                     .serviceName(serviceName)
                     .build()) {
            group.whenReady().join();
            assertThat(group.endpoints()).isNotEmpty();
            for (Endpoint endpoint : group.endpoints()) {
                assertThat(endpoint.host()).isNotEmpty();
                assertThat(endpoint.port()).isGreaterThan(0);
            }
        }
    }

    private static boolean isKubernetesAvailable() {
        if (System.getenv("KUBECONFIG") != null) {
            return true;
        }
        final String home = System.getProperty("user.home");
        return new java.io.File(home, ".kube/config").isFile();
    }
}

