private static Node createNode(KubernetesClient client, String name, Map<String, String> addresses) {
        final NodeFluent.StatusNested<NodeBuilder> nodeStatus = new NodeBuilder()
                .withNewMetadata().withName(name).endMetadata()
                .withNewSpec().endSpec()
                .withNewStatus();
        for (Map.Entry<String, String> entry : addresses.entrySet()) {
            nodeStatus.addNewAddress().withType(entry.getKey()).withAddress(entry.getValue()).endAddress();
        }
        final Node node = nodeStatus.endStatus().build();
        client.nodes().create(node);
        return node;
    }

